      if (line === 'dependencies = [') { if (fields.has('dependencies')) throw new Error('SDK依赖锁字段重复'); fields.set('dependencies', true); dependencies = true; continue; }
      const match = line.match(/^(name|version|source|checksum) = "([^"\\\r\n]+)"$/u);
      if (!match || fields.has(match[1])) throw new Error('SDK依赖锁字段无效');
      fields.set(match[1], match[2]);
