    const name = fields.get('name'), version = fields.get('version'), source = fields.get('source'), checksum = fields.get('checksum');
    if (dependencies || !/^[A-Za-z0-9_-]+$/u.test(name ?? '') || !/^\d+\.\d+\.\d+(?:[-+][A-Za-z0-9.+-]+)?$/u.test(version ?? '')) throw new Error('SDK依赖锁坐标无效');
